// 貪欲な壺とD・モバホン：シャッフルに関するＱ＆Ａを更新。
(function () {
 const updates = [
  {
    "name": "貪欲な壺",
    "id": "R-2SX56XBX6U",
    "question": "対象のモンスター5体が全てエクストラデッキに戻った場合、2枚ドローする前にメインデッキをシャッフルしますか？",
    "answer": "本サイトでは、試合時間短縮のため、メインデッキをシャッフルせず、そのまま2枚ドローすることを推奨します。\n\n[[補足:裁定の経緯]]\n▷2011年8月は「調整中」、2012年2月は「シャッフルする」、2015年8月は「シャッフルしない」と、記録されている回答が変化しています。\n▷当時は「シャッフルする」裁定が有力でしたが、本サイトでは試合時間短縮のため、メインデッキにカードが戻らないこのケースではシャッフルしないことを推奨します。\n[[/補足]]\n\n※この裁定は難解なルールを含むため、大会当日のジャッジの判断を優先してください。",
    "difficult": true
  },
  {
    "name": "D・モバホン",
    "id": "R-ULLCORHA",
    "question": "攻撃表示の効果でサイコロの目が1で、めくった「Ｄ」モンスターを特殊召喚しました。デッキに戻すカードがない場合もシャッフルしますか？",
    "answer": "本サイトでは、試合時間短縮のため、デッキに戻すカードがないこの場合はシャッフルしないことを推奨します。\n\n[[補足:裁定記録とゲームでの処理]]\n▷2009年5月には「シャッフルする」との裁定記録があります。\n▷『遊戯王ファイブディーズ WORLD CHAMPIONSHIP 2011』ではシャッフルしない処理が確認されており、2026年10月のOCG事務局への確認でも「シャッフルしない」との回答でした。\n▷当時のOCG裁定がいつ変わったかは確認できていません。デッキに戻るカードがない場合の本サイトの推奨については、《貪欲な壺》のＱ＆Ａも参照してください。\n[[/補足]]\n\n※この裁定は難解なルールを含むため、大会当日のジャッジの判断を優先してください。",
    "difficult": true
  }
];
 for (const {name, id, ...data} of updates) {
  const card = window.RULINGS.find(item => item.name === name);
  const qa = card?.qa?.find(entry => entry.managementId === id);
  if (!qa) throw new Error("Missing Q&A: " + name + " " + id);
  Object.assign(qa, data);
 }
})();
